import AppKit
import CryptoKit

/// Memantau NSPasteboard dan menyimpan setiap perubahan ke ClipStore.
final class ClipboardWatcher: NSObject {
    private let store: ClipStore
    private var timer: Timer?
    private var lastChange: Int

    /// Tipe pasteboard yang menandakan data rahasia / sementara (lihat nspasteboard.org).
    static let ignoredTypes: Set<String> = [
        "org.nspasteboard.TransientType",
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
    ]

    /// Aplikasi pengelola kata sandi yang tidak pernah direkam.
    static let ignoredApps: Set<String> = [
        "com.apple.keychainaccess",
        "com.apple.Passwords",
        "com.1password.1password",
        "com.agilebits.onepassword7",
        "com.bitwarden.desktop",
        "in.sinew.Enpass-Desktop",
        "com.dashlane.dashlanephonefinal",
    ]

    init(store: ClipStore) {
        self.store = store
        self.lastChange = NSPasteboard.general.changeCount
        super.init()
    }

    func start() {
        let timer = Timer(timeInterval: 0.35, target: self, selector: #selector(poll), userInfo: nil, repeats: true)
        timer.tolerance = 0.1
        RunLoop.main.add(timer, forMode: .common)
        self.timer = timer
    }

    @objc private func poll() {
        let pb = NSPasteboard.general
        guard pb.changeCount != lastChange else { return }
        lastChange = pb.changeCount
        guard !AppSettings.shared.paused else { return }

        let types = Set((pb.types ?? []).map(\.rawValue))
        guard types.isDisjoint(with: Self.ignoredTypes) else { return }

        let app = NSWorkspace.shared.frontmostApplication
        if let bundleID = app?.bundleIdentifier, Self.ignoredApps.contains(bundleID) { return }

        if let item = capture(pb, app: app) {
            store.add(item)
        }
    }

    private func capture(_ pb: NSPasteboard, app: NSRunningApplication?) -> ClipItem? {
        let bundleID = app?.bundleIdentifier
        let appName = app?.localizedName

        // 1. File dari Finder
        if let urls = pb.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL],
           !urls.isEmpty {
            let text = urls.map(\.path).joined(separator: "\n")
            return ClipItem(kind: .file, text: text, contentHash: Self.hash(text),
                            sourceBundleID: bundleID, sourceAppName: appName, date: Date())
        }

        // 2. Teks / tautan / warna
        if let raw = pb.string(forType: .string) {
            let trimmed = raw.trimmingCharacters(in: .whitespacesAndNewlines)
            if !trimmed.isEmpty {
                let kind = Self.classify(trimmed)
                var stored = kind == .text ? raw : trimmed
                if stored.count > 1_000_000 { stored = String(stored.prefix(1_000_000)) }
                return ClipItem(kind: kind, text: stored, contentHash: Self.hash(stored),
                                sourceBundleID: bundleID, sourceAppName: appName, date: Date())
            }
        }

        // 3. Gambar
        if let (data, size) = Self.pngData(pb) {
            let fileName = UUID().uuidString + ".png"
            do {
                try data.write(to: store.imagesDir.appendingPathComponent(fileName), options: .atomic)
            } catch {
                return nil
            }
            return ClipItem(kind: .image, text: "", imageFile: fileName,
                            imageWidth: Double(size.width), imageHeight: Double(size.height),
                            contentHash: Self.hash(data),
                            sourceBundleID: bundleID, sourceAppName: appName, date: Date())
        }
        return nil
    }

    /// Menulis item kembali ke clipboard tanpa merekamnya ulang.
    func write(_ item: ClipItem) {
        let pb = NSPasteboard.general
        pb.clearContents()
        switch item.kind {
        case .text, .color:
            pb.setString(item.text, forType: .string)
        case .link:
            pb.setString(item.text, forType: .string)
            pb.setString(item.text, forType: .URL)
        case .image:
            if let url = store.imageURL(for: item), let data = try? Data(contentsOf: url) {
                pb.setData(data, forType: .png)
                if let tiff = NSImage(data: data)?.tiffRepresentation {
                    pb.setData(tiff, forType: .tiff)
                }
            }
        case .file:
            pb.writeObjects(item.fileURLs as [NSURL])
        }
        lastChange = pb.changeCount
    }

    // MARK: - Helper

    static func classify(_ s: String) -> ClipKind {
        if s.range(of: #"^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})$"#, options: .regularExpression) != nil {
            return .color
        }
        if s.count < 2048,
           !s.contains(where: { $0.isWhitespace }),
           let url = URL(string: s),
           let scheme = url.scheme?.lowercased(),
           ["http", "https", "ftp", "mailto"].contains(scheme),
           scheme == "mailto" || url.host != nil {
            return .link
        }
        return .text
    }

    private static func pngData(_ pb: NSPasteboard) -> (Data, CGSize)? {
        let data: Data
        if let png = pb.data(forType: .png) {
            data = png
        } else if let tiff = pb.data(forType: .tiff),
                  let rep = NSBitmapImageRep(data: tiff),
                  let png = rep.representation(using: .png, properties: [:]) {
            data = png
        } else {
            return nil
        }
        guard data.count < 25_000_000, let rep = NSBitmapImageRep(data: data) else { return nil }
        return (data, CGSize(width: rep.pixelsWide, height: rep.pixelsHigh))
    }

    static func hash(_ text: String) -> String { hash(Data(text.utf8)) }

    static func hash(_ data: Data) -> String {
        SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }
}
